<?php
declare(strict_types=1);
if(!defined('ANISHOP_INSTALL_ENTRY')){http_response_code(403);exit('این فایل را از install.php باز کنید.');}
require_once __DIR__.'/lib.php';
$installed=is_file(__DIR__.'/config.php');
$error='';$success=false;
$published=false;$lock=null;
if($_SERVER['REQUEST_METHOD']==='POST'&&!$installed){
 try{
  check_csrf($_POST['csrf']??null);if(!hash_equals(require __DIR__.'/install-secret.php',(string)($_POST['install_key']??'')))throw new AppError('کلید نصب صحیح نیست. کلید را از راهنمای داخل بسته بردارید.');
  if(empty($_SERVER['HTTPS'])||$_SERVER['HTTPS']==='off'){if(!in_array($_SERVER['SERVER_NAME']??'',['localhost','127.0.0.1'],true))throw new AppError('ابتدا HTTPS زیردامنه را فعال کنید و نصب را با https باز کنید.');}
  $host=trim((string)($_POST['host']??'localhost'));$port=(int)($_POST['port']??3306);$name=trim((string)($_POST['database']??''));$dbuser=trim((string)($_POST['dbuser']??''));$dbpass=(string)($_POST['dbpass']??'');
  $adminName=trim((string)($_POST['name']??''));$adminEmail=strtolower(trim((string)($_POST['email']??'')));$adminUser=strtolower(trim((string)($_POST['username']??'')));$password=(string)($_POST['password']??'');
  if(!preg_match('/^[a-zA-Z0-9._-]+$/D',$host)||$port<1||$port>65535||!preg_match('/^[a-zA-Z0-9_-]+$/D',$name)||!$dbuser)throw new AppError('مشخصات پایگاه داده را بررسی کنید.');
  if(!$adminName||text_length($adminName)>100||!filter_var($adminEmail,FILTER_VALIDATE_EMAIL)||strlen($adminEmail)>254||!preg_match('/^[a-z0-9_.-]{3,60}$/D',$adminUser))throw new AppError('نام، ایمیل و نام کاربری مدیر معتبر باشد.');valid_password($password);if($password!==($_POST['confirm']??''))throw new AppError('تکرار رمز با رمز اصلی یکسان نیست.');
  if(!is_writable(__DIR__))throw new AppError('پوشه برنامه قابل نوشتن نیست. مالکیت پوشه و مجوزها را با پشتیبانی هاست بررسی کنید.');
  $lock=@fopen(__DIR__.'/.install.lock','c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))throw new AppError('نصب دیگری در حال اجراست. دوباره تلاش کنید.');if(is_file(__DIR__.'/config.php'))throw new AppError('نصب قبلاً کامل شده است.');
  $db=new PDO('mysql:host='.$host.';port='.$port.';dbname='.$name.';charset=utf8mb4',$dbuser,$dbpass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
  foreach(explode(';',file_get_contents(__DIR__.'/schema.sql')) as $statement)if(trim($statement)!=='')$db->exec($statement);
  if((int)query($db,'SELECT COUNT(*) FROM app_users')->fetchColumn()>0)throw new AppError('این پایگاه داده قبلاً کاربران برنامه دارد. نصب مجدد انجام نشد؛ پایگاه داده خالی و جداگانه انتخاب کنید.');
  $config=['host'=>$host,'port'=>$port,'database'=>$name,'username'=>$dbuser,'password'=>$dbpass];$text="<?php\nreturn ".var_export($config,true).";\n";
  if(file_put_contents(__DIR__.'/config.pending.php',$text,LOCK_EX)===false)throw new AppError('امکان نوشتن تنظیمات نیست. مجوز پوشه برنامه را با پشتیبانی هاست بررسی کنید.');@chmod(__DIR__.'/config.pending.php',0600);
  $db->beginTransaction();insert_row($db,'app_users',['id'=>uid(),'name'=>$adminName,'username'=>$adminUser,'email'=>$adminEmail,'password_hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>'admin','active'=>1,'created_at'=>now(),'updated_at'=>now()]);
  if(!rename(__DIR__.'/config.pending.php',__DIR__.'/config.php'))throw new AppError('ذخیره تنظیمات کامل نشد.');$published=true;$db->commit();flock($lock,LOCK_UN);fclose($lock);$success=true;$published=false;
 }catch(Throwable $err){
  if(isset($db)&&$db->inTransaction())$db->rollBack();if($published&&is_file(__DIR__.'/config.php'))unlink(__DIR__.'/config.php');
  if($err instanceof AppError)$error=$err->getMessage();elseif($err instanceof PDOException){$number=(int)($err->errorInfo[1]??0);$error=match($number){1045=>'نام کاربر یا رمز دیتابیس صحیح نیست، یا کاربر به دیتابیس وصل نشده است.',1049=>'دیتابیس پیدا نشد. نام کاملِ دارای پیشوند هاست را وارد کنید.',2002,2003,2005=>'اتصال به میزبان دیتابیس برقرار نشد. مقدار host و port را از پشتیبانی هاست بپرسید.',1142,1044=>'کاربر دیتابیس مجوز کافی ندارد. کاربر را به این دیتابیس وصل کنید و ALL PRIVILEGES بدهید.',default=>'ساخت جدول‌های دیتابیس انجام نشد. کد خطا: '.($number?:$err->getCode()).'؛ این کد را به پشتیبانی هاست بدهید.'};}else{$error='نصب کامل نشد. PHP، فایل‌های بسته و مجوز پوشه را بررسی کنید.';}
 }finally{if(is_resource($lock)){flock($lock,LOCK_UN);fclose($lock);}}
}
