<script>const form=document.getElementById('install-form');const box=document.getElementById('install-error');function showError(text){box.hidden=false;document.getElementById('error-text').textContent=text;box.scrollIntoView({behavior:'smooth',block:'start'});}if(form){form.addEventListener('submit',e=>{const invalid=[...form.elements].find(el=>el.validity&&!el.validity.valid);if(invalid){e.preventDefault();const label=invalid.closest('label')?.firstChild?.textContent||'اطلاعات';showError('فیلد «'+label.trim()+'» کامل یا معتبر نیست.');invalid.focus();return;}if(form.password.value!==form.confirm.value){e.preventDefault();showError('تکرار رمز مدیر با رمز اصلی یکسان نیست.');form.confirm.focus();return;}const button=document.getElementById('install-submit');button.disabled=true;button.textContent='در حال اتصال و نصب…';document.getElementById('install-status').textContent='منتظر نتیجه بمانید؛ نصب را دوباره شروع نکنید.';setTimeout(()=>{button.disabled=false;button.textContent='نصب و ساخت حساب مدیر';document.getElementById('install-status').textContent='پاسخ هنوز دریافت نشده؛ اتصال هاست را بررسی کنید.';},15000);});document.querySelectorAll('.show-pass').forEach(btn=>btn.addEventListener('click',()=>{const input=btn.previousElementSibling;input.type=input.type==='password'?'text':'password';btn.textContent=input.type==='password'?'نمایش':'پنهان';}));}<?php if($error):?>box?.scrollIntoView({block:'start'});<?php endif;?></script></body></html>